theorem idealsUpToNormCount_nat_eq_sum_normFibers (K : Type) [Field K] [NumberField K] (n : ℕ) :
    idealsUpToNormCount K (n : ℝ) =
      ∑ k ∈ Finset.Icc 1 n, Nat.card {I : Ideal (𝓞 K) // Ideal.absNorm I = k}

